import {cleanPublicDesign} from './public-design.js';
import {compressGiftPhotos} from './media-compression.js';
import {ornamentArtwork} from './gift-identity.js';
import {giftArtworkSource} from './appearance.js';
import {downloadFile,node} from './experience.js';
const asDataURL=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
const localSource=async path=>{const response=await fetch(path);if(!response.ok)throw Error('Arquivo indisponível: '+path);return response.text();};
export async function makeDigitalGift(data,audio){
 data=await compressGiftPhotos(data);
 if(data.format&&data.format!=='stories'){const {makePortableObject}=await import('./portable-export.js');return makePortableObject(data,audio);}
 const [experience,sound,stories,design,appearance,identity,layout,css,fonts]=await Promise.all(['experience.js','audio-studio.js','stories.js','story-design.js','appearance.js','gift-identity.js','text-layout.js','digital.css','fonts.css'].map(localSource));
 const fontEntries=await Promise.all([...fonts.matchAll(/url\(([^)]+)\)/g)].map(async match=>[match[0],'url('+await asDataURL(await(await fetch(match[1])).blob())+')']));let fontCSS=fonts;for(const [from,to] of fontEntries)fontCSS=fontCSS.replace(from,to);
 const storyAssets={};for(const [key,path] of Object.entries({decor:'assets/'+(data.theme?.sheet||'classic')+'.webp',envelope:'assets/hero-motion-envelope.webp',pattern:giftArtworkSource(data)})){const response=await fetch(path);if(response.ok)storyAssets[key]=await asDataURL(await response.blob());}
 storyAssets.ornaments={};await Promise.all(Object.values(ornamentArtwork).map(async path=>{const response=await fetch(path);if(!response.ok)throw Error('Ilustração indisponível');storyAssets.ornaments[path]=await asDataURL(await response.blob());}));
 const photos=await Promise.all((data.photos?.length?data.photos:data.photo?[{src:data.photo}]:[]).map(async photo=>{const src=photo.src.startsWith('data:')?photo.src:await asDataURL(await(await fetch(photo.src)).blob());return {...photo,src};}));
 const payload={...cleanPublicDesign(data,photos),color:data.color,texture:data.texture,pattern:data.pattern,coverArt:data.coverArt,openingStyle:data.openingStyle,eventDate:data.eventDate,eventPlace:data.eventPlace,theme:data.theme,character:data.character,person:data.person,occasion:data.occasion,appearance:data.appearance,draftId:data.draftId,storyDesign:data.storyDesign,storyAssets,format:'stories',recipient:data.recipient,message:data.message,occasionLabel:data.theme?.label,photo:data.photo,photos,experience:data.experience,audioUrl:audio?.blob?await asDataURL(audio.blob):''};
 const strip=source=>source.replace(/^import .*?;\s*/gm,'').replace(/\bexport (?=(?:async )?function|const )/g,'');
 const runtime=[strip(appearance),strip(identity),strip(layout),strip(design),strip(experience),strip(sound.split('export function initAudioStudio')[0]),strip(stories)].join('\n').replace(/<\/script/gi,'<\\/script');
 const json=JSON.stringify(payload).replaceAll('<','\\u003c').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
 return new Blob([`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Um mimo para você</title><style>${fontCSS}\n${css}</style><body class="standalone-gift"><main><h1>Tem um mimo para você.</h1><p>Suas memórias ficam neste arquivo. Abra com um navegador para ver e ouvir.</p><button class="button primary" id="open-present">Abrir meu presente</button><p>Para guardar, conserve este arquivo. Uma resposta baixada precisa ser enviada por você.</p></main><script type="application/json" id="capimimo-payload">${json}<\/script><script>${runtime}\nconst gift=JSON.parse(document.getElementById("capimimo-payload").textContent);const viewer=createStoriesViewer();document.getElementById('open-present').addEventListener('click',()=>viewer.show(gift));viewer.show(gift);if(window.parent!==window)window.parent.postMessage({type:'capimimo:ready'},'*');<\/script></body></html>`],{type:'text/html;charset=utf-8'});
}
export function initDigitalExport({getData,getAudio,toast,authorize=async()=>true}){
 const panel=node('section','digital-delivery');panel.innerHTML='<h3>Guarde e compartilhe a história.</h3><p>Baixe o presente no formato escolhido, com fotos, carta e áudio dentro do arquivo. Livro, cartão e convite preservam a visualização em 3D. Envie o arquivo para quem vai receber. Não depende de um link publicado.</p><button class="button primary" type="button">Baixar presente digital</button><p class="digital-export-status" role="status"></p><small>O arquivo abre no navegador. No celular, pode ser necessário salvar e escolher “Abrir com”. Links de músicas abrem a plataforma e precisam de internet.</small>';
 document.querySelector('.customizer-bottom').before(panel);const button=panel.querySelector('button'),status=panel.querySelector('[role=status]');let busy=false;
 button.addEventListener('click',async()=>{if(busy)return;busy=true;button.disabled=true;status.textContent='Conferindo acesso e preparando suas mídias…';try{if(!await authorize()){status.textContent='Download não realizado. Confira o acesso à compra para baixar este presente.';return;}status.textContent='Preparando fotos e áudio…';const data=getData();if(!data.photos?.length&&!data.message&&!data.experience?.letter){status.textContent='Adicione uma foto ou escreva uma mensagem para começar.';return;}const file=await makeDigitalGift(data,getAudio());downloadFile('capimimo-presente.html',file);status.textContent='Presente baixado. Envie o arquivo para a pessoa abrir no navegador.';toast('Seu presente digital está pronto para guardar.');}catch{status.textContent='Não foi possível preparar o arquivo. Suas fotos e seu rascunho continuam aqui.';}finally{busy=false;button.disabled=false;}});
}
